"""Generate SYNTHETIC Open-Meteo Previous Runs responses for tests and CI.

NOT REAL WEATHER DATA. The numbers are made up by a seeded random generator; only the response
shape follows the documented API: one object per location, `hourly.time` in unix seconds, and
`<var>` plus `<var>_previous_dayN` lists of equal length.

Covers two corridors (den_vail_i70, sea_pdx_i5) for 3 days (2026-10-01..2026-10-03), with a mix of
dry and wet hours: day 1 mostly dry, day 2 afternoon showers, day 3 a frontal rain band.
Forecasts get noisier with lead time, so accuracy falls as lead_day grows.

Run from pipeline/:  python tests/fixtures/generate_synthetic.py
"""

from __future__ import annotations

import csv
import json
import random
from datetime import UTC, datetime
from pathlib import Path

HERE = Path(__file__).resolve().parent
SEEDS = HERE.parent.parent / "dbt" / "seeds"
CORRIDORS = ("den_vail_i70", "sea_pdx_i5")
START = datetime(2026, 10, 1, tzinfo=UTC)
HOURS = 72
LEADS = (1, 2, 3, 4, 5)


def corridor_points() -> list[tuple[float, float, float]]:
    """(lat, lng, eta_hours) of the points of the fixture corridors, de-duplicated."""
    out: dict[tuple[float, float], float] = {}
    with (SEEDS / "corridor_points.csv").open() as f:
        for row in csv.DictReader(f):
            if row["corridor_id"] in CORRIDORS:
                out.setdefault((float(row["lat"]), float(row["lng"])), float(row["eta_hours"]))
    return [(lat, lng, eta) for (lat, lng), eta in out.items()]


def true_wetness(hour: int, shift: float) -> float:
    """Underlying 0..1 wetness of the weather at `hour`, moving west to east with `shift` hours."""
    h = hour - shift
    day, hod = divmod(h, 24)
    if day < 1:
        return 0.0
    if day < 2:  # afternoon showers
        return 0.7 if 12 <= hod <= 18 else 0.05
    return 0.95 if 6 <= hod <= 20 else 0.3  # frontal rain band


def location(rng: random.Random, lat: float, lng: float, shift: float) -> dict:
    times = [int(START.timestamp()) + 3600 * i for i in range(HOURS)]
    obs_code: list[int] = []
    obs_precip: list[float] = []
    is_day: list[int] = []
    wet_level: list[float] = []
    for i in range(HOURS):
        w = true_wetness(i, shift)
        wet_level.append(w)
        wet = rng.random() < w
        obs_code.append(rng.choice([61, 63, 80]) if wet else rng.choice([0, 1, 2, 3]))
        obs_precip.append(round(rng.uniform(0.2, 3.0), 1) if wet else 0.0)
        is_day.append(1 if (i % 24) >= 14 or (i % 24) <= 1 else 0)  # roughly US daylight in UTC
    hourly: dict[str, list] = {
        "time": times,
        "weather_code": obs_code,
        "precipitation": obs_precip,
        "is_day": is_day,
    }
    for n in LEADS:
        noise = 0.12 * n  # forecasts degrade with lead
        codes, pops, temps, winds, gusts = [], [], [], [], []
        for i in range(HOURS):
            seen = min(1.0, max(0.0, wet_level[i] + rng.uniform(-noise, noise) * 2))
            wet = rng.random() < seen
            codes.append(rng.choice([61, 63, 80]) if wet else rng.choice([0, 1, 2, 3]))
            pops.append(int(round(seen * 100 / 10) * 10))
            temps.append(round(rng.uniform(28, 62), 1))
            winds.append(round(rng.uniform(2, 24), 1))
            gusts.append(round(rng.uniform(8, 48), 1))
        hourly[f"weather_code_previous_day{n}"] = codes
        hourly[f"precipitation_probability_previous_day{n}"] = pops
        hourly[f"temperature_2m_previous_day{n}"] = temps
        hourly[f"wind_speed_10m_previous_day{n}"] = winds
        hourly[f"wind_gusts_10m_previous_day{n}"] = gusts
    return {
        "_synthetic": "NOT REAL DATA - generated by tests/fixtures/generate_synthetic.py",
        "latitude": lat,
        "longitude": lng,
        "generationtime_ms": 0.1,
        "utc_offset_seconds": 0,
        "timezone": "GMT",
        "timezone_abbreviation": "GMT",
        "elevation": 0.0,
        "hourly_units": {"time": "unixtime", "temperature_2m_previous_day1": "°F"},
        "hourly": hourly,
    }


def main() -> None:
    rng = random.Random(20261001)
    locs = [location(rng, lat, lng, eta * 0.8) for lat, lng, eta in corridor_points()]
    out = HERE / "synthetic_previous_runs.json"
    out.write_text(json.dumps(locs, separators=(",", ":")) + "\n")
    print(f"wrote {len(locs)} locations to {out}")


if __name__ == "__main__":
    main()
